macro_rules! generate_impl_text_inner {
    () => {
        fn generate_impl_text_inner (adt : & ast :: Adt , trait_text : Option < & str > , trait_is_transitive : bool , code : & str ,) -> String { let generic_params = adt . generic_param_list () . map (| generic_params | { let lifetime_params = generic_params . lifetime_params () . map (ast :: GenericParam :: LifetimeParam) ; let ty_or_const_params = generic_params . type_or_const_params () . filter_map (| param | { let param = match param { ast :: TypeOrConstParam :: Type (param) => { let mut bounds = param . type_bound_list () . map_or_else (Vec :: new , | it | it . bounds () . collect ()) ; if let Some (trait_) = trait_text { if trait_is_transitive { bounds . push (make :: type_bound_text (trait_)) ; } } ; let param = make :: type_param (param . name () ? , make :: type_bound_list (bounds)) ; ast :: GenericParam :: TypeParam (param) } ast :: TypeOrConstParam :: Const (param) => { let param = make :: const_param (param . name () ? , param . ty () ?) ; ast :: GenericParam :: ConstParam (param) } } ; Some (param) }) ; make :: generic_param_list (itertools :: chain (lifetime_params , ty_or_const_params)) }) ; let mut buf = String :: with_capacity (code . len ()) ; buf . push_str ("\n\n") ; let cfg_attrs = adt . attrs () . filter (| attr | attr . as_simple_call () . map (| (name , _arg) | name == "cfg") . unwrap_or (false)) ; cfg_attrs . for_each (| attr | buf . push_str (& format ! ("{attr}\n"))) ; buf . push_str ("impl") ; if let Some (generic_params) = & generic_params { format_to ! (buf , "{generic_params}") ; } buf . push (' ') ; if let Some (trait_text) = trait_text { buf . push_str (trait_text) ; buf . push_str (" for ") ; } buf . push_str (& adt . name () . unwrap () . text ()) ; if let Some (generic_params) = generic_params { format_to ! (buf , "{}" , generic_params . to_generic_args ()) ; } match adt . where_clause () { Some (where_clause) => { format_to ! (buf , "\n{where_clause}\n{{\n{code}\n}}") ; } None => { format_to ! (buf , " {{\n{code}\n}}") ; } } buf }
    };
}

generate_impl_text_inner!()